"""Bridge ABI framing through actual generated bytecode, not a BF proxy."""
from __future__ import annotations
import json
import tempfile
import unittest
from pathlib import Path
import zipfile

from toolchain.brainfuck.build import build
from toolchain.brainfuck.host_abi import ABIError,FEATURE_IDS,Request,Reply,load_programs
from toolchain.brainfuck.host_link import exercise_aot_frames,verify_jar

class HostLinkTests(unittest.TestCase):
    def test_framed_actions_from_real_jvm(self):
        programs=load_programs()
        frames=[]
        for name,fid in FEATURE_IDS.items():
            if name in {'authorize_seek','select_sponsor_category','sponsor_skip_pipeline','sponsor_time_window'}:continue
            count=programs[fid].metadata['inputs'].count(' (0 or 1)')
            for enabled in (False,True):
                bits=[1]*count
                if not enabled:bits[0]=0
                if name=='suppress_video_slot':bits[-1]=0
                frames.append(Request(fid,99,bytes(bits)).pack())
        with tempfile.TemporaryDirectory() as tmp:
            for opt in (False,True):
                root=Path(tmp)/str(opt)
                jar=build(root,optimize=opt)
                replies=exercise_aot_frames(frames,jar=jar,manifest=root/'policies.json',optimized=opt,active_generation=99)
                self.assertEqual(len(replies),len(frames))
                for request,reply in zip(frames,replies):
                    req=Request.unpack(request);rep=Reply.unpack(reply)
                    self.assertEqual(req.feature_id,rep.feature_id)
                    self.assertEqual(rep.action,0 if not req.data[0] else (3 if req.feature_id==0x0301 else 2 if req.feature_id==0x0201 else 1))

    def test_reject_corrupted_jar_and_manifest(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp)
            jar=build(root)
            mf=root/'policies.json'
            verify_jar(jar,mf)
            registry=json.loads(mf.read_text())
            registry['suppress_feed_item']['sha256']='0'*64
            mf.write_text(json.dumps(registry))
            with self.assertRaises(ABIError) as cm:verify_jar(jar,mf)
            self.assertEqual(cm.exception.code,'JAR_SOURCE_DIGEST_MISMATCH')
            build(root)
            files={}
            with zipfile.ZipFile(jar) as z:
                for name in z.namelist():files[name]=z.read(name)
            key=next(iter(files));files[key]=files[key][:-1]+bytes([files[key][-1]^1])
            with zipfile.ZipFile(jar,'w') as z:
                for name,data in files.items():z.writestr(name,data)
            with self.assertRaises(ABIError) as cm:verify_jar(jar,mf)
            self.assertEqual(cm.exception.code,'STALE_OR_TAMPERED_CLASS')

    def test_jvm_bridge_rejects_malformed_and_stale_frames(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);jar=build(root)
            with self.assertRaises(ABIError) as cm:
                exercise_aot_frames([Request(0x0102,10,b'\x01\x01\x01').pack()],jar=jar,manifest=root/'policies.json',active_generation=11)
            self.assertEqual(cm.exception.code,'STALE_GENERATION')
            with self.assertRaises(ABIError) as cm:
                exercise_aot_frames([Request(0x0102,11,b'\x00\x00\x02').pack()],jar=jar,manifest=root/'policies.json',active_generation=11)
            self.assertEqual(cm.exception.code,'NON_BOOLEAN_INPUT')

if __name__=='__main__':unittest.main()
